import "../styles/index.scss";
import {Tooltip} from "bootstrap/dist/js/bootstrap.bundle";
import '@fortawesome/fontawesome-free/css/all.css';
import {on_market} from "../components/msgs";

window.document.addEventListener("DOMContentLoaded", function () {
    const container = document.querySelector('#homeHeader');

    if (container) {
        const root = document.documentElement;
        const reducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)');
        const idleDelay = 1800;
        const baseInnerRadius = 40;
        const baseOuterRadius = 150;

        let cursorX = 60;
        let cursorY = 40;
        let currentX = cursorX;
        let currentY = cursorY;
        let walkStartX = cursorX;
        let walkStartY = cursorY;
        let walkTargetX = cursorX;
        let walkTargetY = cursorY;
        let targetChangedAt = 0;
        let inactivityTimeout;
        let idleAnimationFrame;
        let idleStartedAt;
        let isIdleAnimating = false;

        function clamp(value, min, max) {
            return Math.min(max, Math.max(min, value));
        }

        function easeInOutSine(progress) {
            return -(Math.cos(Math.PI * progress) - 1) / 2;
        }

        function updateSpotlight(x, y, innerRadius = baseInnerRadius, outerRadius = baseOuterRadius) {
            root.style.setProperty('--mouse-x', `${clamp(x, 4, 96)}%`);
            root.style.setProperty('--mouse-y', `${clamp(y, 4, 96)}%`);
            root.style.setProperty('--spotlight-inner', `${innerRadius}px`);
            root.style.setProperty('--spotlight-outer', `${outerRadius}px`);
            currentX = x;
            currentY = y;
        }

        function chooseNextWalkTarget() {
            walkStartX = currentX;
            walkStartY = currentY;

            const angle = Math.random() * Math.PI * 2;
            const distance = 7 + (Math.random() * 10);

            walkTargetX = clamp(walkStartX + Math.cos(angle) * distance, 16, 84);
            walkTargetY = clamp(walkStartY + Math.sin(angle) * distance, 14, 86);
        }

        function startIdleAnimation() {
            if (isIdleAnimating || reducedMotion.matches || document.hidden) return;

            isIdleAnimating = true;
            idleStartedAt = undefined;
            targetChangedAt = 0;
            chooseNextWalkTarget();

            function animateIdleSpotlight(timestamp) {
                if (idleStartedAt === undefined) {
                    idleStartedAt = timestamp;
                    targetChangedAt = timestamp;
                }

                if (timestamp - targetChangedAt > 3600) {
                    chooseNextWalkTarget();
                    targetChangedAt = timestamp;
                }

                const elapsed = timestamp - idleStartedAt;
                const targetProgress = easeInOutSine(clamp((timestamp - targetChangedAt) / 3600, 0, 1));
                const x = walkStartX + ((walkTargetX - walkStartX) * targetProgress);
                const y = walkStartY + ((walkTargetY - walkStartY) * targetProgress);
                const breath = Math.sin(elapsed * 0.0024);

                updateSpotlight(
                    x,
                    y,
                    baseInnerRadius + (breath * 7),
                    baseOuterRadius + (breath * 12),
                );

                idleAnimationFrame = window.requestAnimationFrame(animateIdleSpotlight);
            }

            idleAnimationFrame = window.requestAnimationFrame(animateIdleSpotlight);
        }

        function stopIdleAnimation() {
            window.cancelAnimationFrame(idleAnimationFrame);
            isIdleAnimating = false;
            idleStartedAt = undefined;
        }

        function resetInactivityTimer() {
            clearTimeout(inactivityTimeout);
            if (reducedMotion.matches) return;

            inactivityTimeout = setTimeout(() => {
                startIdleAnimation();
            }, idleDelay);
        }

        document.addEventListener('visibilitychange', () => {
            if (document.hidden) {
                stopIdleAnimation();
            } else {
                resetInactivityTimer();
            }
        });

        reducedMotion.addEventListener('change', () => {
            stopIdleAnimation();
            updateSpotlight(cursorX, cursorY);
            resetInactivityTimer();
        });

        container.addEventListener('pointermove', (e) => {
            const rect = container.getBoundingClientRect();
            const x = ((e.clientX - rect.left) / rect.width) * 100;
            const y = ((e.clientY - rect.top) / rect.height) * 100;

            stopIdleAnimation();
            cursorX = x;
            cursorY = y;
            currentX = x;
            currentY = y;
            updateSpotlight(cursorX, cursorY);
            resetInactivityTimer();
        });

        updateSpotlight(cursorX, cursorY);
        resetInactivityTimer();
    }

    // enable tooltips
    const tooltipTriggerList = document.querySelectorAll('[data-bs-toggle="tooltip"]');
    [...tooltipTriggerList].map(tooltipTriggerEl => new Tooltip(tooltipTriggerEl));

    on_market();
});
